"""
Example: NGINX as a Load Balancer
Production configuration for Python web applications
"""

# nginx.conf
NGINX_CONFIG = """
# Define upstream servers
upstream python_app {
    # Load balancing method: least_conn, ip_hash, or round-robin (default)
    least_conn;

    # Server pool with weights and parameters
    server 10.0.0.1:8000 weight=5;    # Gets 50% traffic
    server 10.0.0.2:8000 weight=3;    # Gets 30% traffic
    server 10.0.0.3:8000 weight=2;    # Gets 20% traffic

    # Backup server (only used when all others are down)
    server 10.0.0.4:8000 backup;

    # Health check parameters
    server 10.0.0.5:8000 max_fails=3 fail_timeout=30s;

    # Keepalive connections to upstream
    keepalive 32;
}

# HTTP server block
server {
    listen 80;
    server_name api.example.com;

    # Redirect HTTP to HTTPS
    return 301 https://$server_name$request_uri;
}

# HTTPS server block
server {
    listen 443 ssl http2;
    server_name api.example.com;

    # SSL configuration
    ssl_certificate /etc/ssl/certs/example.crt;
    ssl_certificate_key /etc/ssl/private/example.key;
    ssl_protocols TLSv1.2 TLSv1.3;

    # Proxy settings
    location / {
        proxy_pass http://python_app;
        proxy_http_version 1.1;

        # Headers to pass to upstream
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;

        # Keepalive to upstream
        proxy_set_header Connection "";

        # Timeouts
        proxy_connect_timeout 10s;
        proxy_send_timeout 60s;
        proxy_read_timeout 60s;

        # Retry on failure
        proxy_next_upstream error timeout http_502 http_503;
        proxy_next_upstream_tries 3;
    }

    # Health check endpoint (bypass load balancing)
    location /health {
        proxy_pass http://127.0.0.1:8000/health;
    }

    # Static files (served by NGINX directly)
    location /static/ {
        alias /var/www/static/;
        expires 30d;
    }
}
"""

# Python helper to generate NGINX config programmatically
from dataclasses import dataclass
from typing import List, Optional
from jinja2 import Template

@dataclass
class UpstreamServer:
    host: str
    port: int
    weight: int = 1
    max_fails: int = 3
    fail_timeout: int = 30
    backup: bool = False

@dataclass
class LoadBalancerConfig:
    upstream_name: str
    servers: List[UpstreamServer]
    method: str = "least_conn"  # round_robin, least_conn, ip_hash
    keepalive: int = 32

class NginxConfigGenerator:
    """Generate NGINX load balancer configuration"""

    UPSTREAM_TEMPLATE = """
upstream {{ upstream_name }} {
    {{ method }};

    {% for server in servers %}
    server {{ server.host }}:{{ server.port }}{% if server.weight != 1 %} weight={{ server.weight }}{% endif %}{% if server.backup %} backup{% endif %} max_fails={{ server.max_fails }} fail_timeout={{ server.fail_timeout }}s;
    {% endfor %}

    keepalive {{ keepalive }};
}
"""

    def generate(self, config: LoadBalancerConfig) -> str:
        template = Template(self.UPSTREAM_TEMPLATE)
        return template.render(
            upstream_name=config.upstream_name,
            method=config.method,
            servers=config.servers,
            keepalive=config.keepalive
        )

# Usage
generator = NginxConfigGenerator()
config = LoadBalancerConfig(
    upstream_name="python_api",
    servers=[
        UpstreamServer("10.0.0.1", 8000, weight=5),
        UpstreamServer("10.0.0.2", 8000, weight=3),
        UpstreamServer("10.0.0.3", 8000, weight=2),
        UpstreamServer("10.0.0.4", 8000, backup=True),
    ],
    method="least_conn"
)
print(generator.generate(config))
