"""
Example: Kubernetes Ingress and Service Load Balancing
Cloud-native load balancing for containerized Python apps
"""

from kubernetes import client, config
import yaml
from typing import List, Dict

class KubernetesLoadBalancer:
    """
    Manage Kubernetes load balancing resources
    """

    def __init__(self, namespace: str = "default"):
        try:
            config.load_incluster_config()
        except:
            config.load_kube_config()

        self.namespace = namespace
        self.core_v1 = client.CoreV1Api()
        self.apps_v1 = client.AppsV1Api()
        self.networking_v1 = client.NetworkingV1Api()

    def create_service(
        self,
        name: str,
        selector: Dict[str, str],
        port: int,
        target_port: int,
        service_type: str = "ClusterIP"
    ):
        """
        Create a Kubernetes Service (internal load balancer)
        """

        service = client.V1Service(
            api_version="v1",
            kind="Service",
            metadata=client.V1ObjectMeta(name=name),
            spec=client.V1ServiceSpec(
                type=service_type,
                selector=selector,
                ports=[
                    client.V1ServicePort(
                        port=port,
                        target_port=target_port,
                        protocol="TCP"
                    )
                ]
            )
        )

        self.core_v1.create_namespaced_service(
            namespace=self.namespace,
            body=service
        )
        print(f"Created Service: {name}")

    def create_ingress(
        self,
        name: str,
        host: str,
        paths: List[dict],
        tls_secret: str = None
    ):
        """
        Create Ingress for external load balancing

        paths: [{"path": "/api", "service": "api-service", "port": 80}]
        """

        ingress_paths = []
        for p in paths:
            ingress_paths.append(
                client.V1HTTPIngressPath(
                    path=p["path"],
                    path_type="Prefix",
                    backend=client.V1IngressBackend(
                        service=client.V1IngressServiceBackend(
                            name=p["service"],
                            port=client.V1ServiceBackendPort(
                                number=p["port"]
                            )
                        )
                    )
                )
            )

        spec = client.V1IngressSpec(
            rules=[
                client.V1IngressRule(
                    host=host,
                    http=client.V1HTTPIngressRuleValue(
                        paths=ingress_paths
                    )
                )
            ]
        )

        if tls_secret:
            spec.tls = [
                client.V1IngressTLS(
                    hosts=[host],
                    secret_name=tls_secret
                )
            ]

        ingress = client.V1Ingress(
            api_version="networking.k8s.io/v1",
            kind="Ingress",
            metadata=client.V1ObjectMeta(
                name=name,
                annotations={
                    "nginx.ingress.kubernetes.io/ssl-redirect": "true",
                    "nginx.ingress.kubernetes.io/proxy-body-size": "10m"
                }
            ),
            spec=spec
        )

        self.networking_v1.create_namespaced_ingress(
            namespace=self.namespace,
            body=ingress
        )
        print(f"Created Ingress: {name}")

    def create_loadbalancer_service(
        self,
        name: str,
        selector: Dict[str, str],
        port: int
    ):
        """
        Create LoadBalancer Service (cloud provider integration)
        """
        self.create_service(
            name=name,
            selector=selector,
            port=port,
            target_port=port,
            service_type="LoadBalancer"
        )

    def generate_full_stack_yaml(
        self,
        app_name: str,
        replicas: int,
        image: str,
        port: int,
        host: str
    ) -> str:
        """
        Generate complete YAML for deployment + service + ingress
        """

        manifests = {
            "deployment": {
                "apiVersion": "apps/v1",
                "kind": "Deployment",
                "metadata": {"name": app_name},
                "spec": {
                    "replicas": replicas,
                    "selector": {"matchLabels": {"app": app_name}},
                    "template": {
                        "metadata": {"labels": {"app": app_name}},
                        "spec": {
                            "containers": [{
                                "name": app_name,
                                "image": image,
                                "ports": [{"containerPort": port}],
                                "resources": {
                                    "requests": {"cpu": "100m", "memory": "128Mi"},
                                    "limits": {"cpu": "500m", "memory": "512Mi"}
                                },
                                "livenessProbe": {
                                    "httpGet": {"path": "/health", "port": port},
                                    "initialDelaySeconds": 10,
                                    "periodSeconds": 10
                                },
                                "readinessProbe": {
                                    "httpGet": {"path": "/ready", "port": port},
                                    "initialDelaySeconds": 5,
                                    "periodSeconds": 5
                                }
                            }]
                        }
                    }
                }
            },
            "service": {
                "apiVersion": "v1",
                "kind": "Service",
                "metadata": {"name": f"{app_name}-service"},
                "spec": {
                    "selector": {"app": app_name},
                    "ports": [{"port": 80, "targetPort": port}],
                    "type": "ClusterIP"
                }
            },
            "ingress": {
                "apiVersion": "networking.k8s.io/v1",
                "kind": "Ingress",
                "metadata": {
                    "name": f"{app_name}-ingress",
                    "annotations": {
                        "nginx.ingress.kubernetes.io/rewrite-target": "/"
                    }
                },
                "spec": {
                    "rules": [{
                        "host": host,
                        "http": {
                            "paths": [{
                                "path": "/",
                                "pathType": "Prefix",
                                "backend": {
                                    "service": {
                                        "name": f"{app_name}-service",
                                        "port": {"number": 80}
                                    }
                                }
                            }]
                        }
                    }]
                }
            }
        }

        yaml_docs = []
        for doc in manifests.values():
            yaml_docs.append(yaml.dump(doc, default_flow_style=False))

        return "\n---\n".join(yaml_docs)

# Usage
k8s_lb = KubernetesLoadBalancer(namespace="production")

# Generate YAML for Python API
yaml_config = k8s_lb.generate_full_stack_yaml(
    app_name="python-api",
    replicas=5,
    image="my-registry/python-api:v1.0",
    port=8000,
    host="api.example.com"
)

print(yaml_config)
